{"code": "async (page) => {
    // Click "View More" up to 10 times or until June 2022 appears
    for (let i = 0; i < 10; i++) {
        const viewMore = page.getByRole('link', { name: 'View More' });
        if (await viewMore.count() === 0) break;
        await viewMore.click();
        await page.waitForTimeout(2000); // wait for load
        // Check if page contains June 2022 heading
        const content = await page.content();
        if (content.includes('June 2022')) {
            console.log('Found June 2022 after', i+1, 'clicks');
            break;
        }
    }
    return true;
}"}

